\set ON_ERROR_STOP on
-- Disposable LOCAL DB only; fixtures model current production dependencies.
create schema auth; create schema storage;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.uid',true),'')::uuid$$;
create function public.is_platform_admin() returns boolean language sql stable as $$select coalesce(current_setting('test.admin',true),'false')='true'$$;
create table stores(id uuid primary key,owner_id uuid references auth.users,name text);
create table orders(id uuid primary key,store_id uuid references stores,buyer_id uuid references auth.users,order_number text,total numeric);
create table chat_messages(id uuid primary key,conversation_id uuid);
create function public.can_access_chat(uuid) returns boolean language sql stable as $$select auth.uid()='11111111-1111-4111-8111-111111111111'::uuid$$;
create table reports(id uuid primary key default gen_random_uuid(),type text,store_id uuid references stores,order_id uuid references orders,reported_by uuid references auth.users,reason text,details text,status text default 'open',created_at timestamptz default now(),product_id uuid,message_id uuid references chat_messages, constraint reports_status_check check(status in('open','resolved')));
alter table reports enable row level security;
create policy "reports: reporter read own" on reports for select using(reported_by=auth.uid());
create policy "reports: seller read own store" on reports for select using(exists(select 1 from stores where id=store_id and owner_id=auth.uid()));
create table notifications(id uuid default gen_random_uuid(),user_id uuid,type text,title text,body text,link text);
create table storage.buckets(id text primary key,name text,public boolean);
create table storage.objects(id uuid,bucket_id text,name text);
alter table storage.objects enable row level security;
create function public.admin_apply_action(p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer as $$ begin if not public.is_platform_admin() then raise exception 'Admin required';end if;if p_action='report_status' then update reports set status=p_payload->>'status' where id=(p_payload->>'reportId')::uuid;end if;return '{"success":true}'::jsonb;end$$;
do $$begin if not exists(select 1 from pg_roles where rolname='service_role')then create role service_role bypassrls;end if;end$$;
alter role service_role bypassrls;
grant usage on schema auth,public,storage to authenticated,anon,service_role;
grant select on auth.users,stores,orders,chat_messages,storage.objects to authenticated,anon,service_role;
\ir ../supabase/stage-76-report-safety-cases.sql
create function expect_error(q text, expected text) returns void language plpgsql as $$ begin begin execute q; exception when others then if sqlerrm not ilike '%'||expected||'%' then raise exception 'Wrong failure: % expected %',sqlerrm,expected; end if; return; end; raise exception 'Expected failure: %',q; end $$;
