 if(select public from storage.buckets where id='report-evidence')then raise exception 'Evidence bucket is public';end if;
 if(select count(distinct case_ref)from reports)<>3 then raise exception 'Case references not unique';end if;
 raise notice 'PASS report tests: buyer/seller isolation, no direct case/status spoofing, legacy chat, role-checked review, private notes, seller requests/responses, buyer updates, audit, unique refs, private bucket';
end$$;
